            }
            ItemBlockRenderTypes.setRenderLayer((Block)((Block)registryObject.get()), (RenderType)RenderType.m_110463_());
        }
        for (RegistryObject<? extends OmniCraftingUnitBlock> registryObject : OCBlocks.CRAFTING_MONITORS) {
            iCraftingUnitType = ((CraftingMonitorBlock)registryObject.get()).type;
