                omniCraftingUnitType = (OmniCraftingUnitType)iCraftingUnitType;
                BuiltInModelHooks.addBuiltInModel((ResourceLocation)AppEng.makeId((String)("block/crafting/" + registryObject.getId().m_135815_() + "_formed")), (UnbakedModel)new CraftingCubeModel((AbstractCraftingUnitModelProvider)new OmniCraftingUnitModelProvider(omniCraftingUnitType)));
